/* Blood Group Variant Database: browser logic.
 * Vanilla JS, no build step, no dependencies. Reads window.VARIANT_DATA
 * (generated by scripts/normalize_data.py from data/variants_raw.json).
 */
(function () {
  "use strict";

  /* ---------------- mobile nav toggle (shared across pages) ---------------- */
  function initNavToggle() {
    var btn = document.getElementById("nav-toggle");
    var nav = document.querySelector(".site-nav");
    if (!btn || !nav) return;
    btn.addEventListener("click", function () {
      var open = nav.classList.toggle("is-open");
      btn.setAttribute("aria-expanded", open ? "true" : "false");
    });
    document.querySelectorAll(".nav-mobile a").forEach(function (a) {
      a.addEventListener("click", function () { nav.classList.remove("is-open"); btn.setAttribute("aria-expanded", "false"); });
    });
  }

  /* ---------------- theme toggle (shared across pages) ---------------- */
  function initTheme() {
    var root = document.documentElement;
    var saved = localStorage.getItem("bgvdb-theme");
    if (saved) root.setAttribute("data-theme", saved);
    var btn = document.querySelector("[data-theme-toggle]");
    if (!btn) return;
    btn.addEventListener("click", function () {
      var current = root.getAttribute("data-theme");
      var prefersDark = window.matchMedia("(prefers-color-scheme: dark)").matches;
      var effectiveCurrent = current || (prefersDark ? "dark" : "light");
      var next = effectiveCurrent === "dark" ? "light" : "dark";
      root.setAttribute("data-theme", next);
      localStorage.setItem("bgvdb-theme", next);
    });
  }

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  /* ---------------- classification helpers ---------------- */
  // Free-text source fields vary in wording across the 8 systems; these
  // bucket them into a small set of filterable/badge-able tiers.
  function categoryBucket(v) {
    var c = (v || "").toLowerCase();
    if (!c) return "Other / Unclassified";
    if (c.indexOf("splice") > -1) return "Splice Site";
    if (c.indexOf("promoter") > -1) return "Promoter";
    if (c.indexOf("5'utr") > -1 || c.indexOf("start codon") > -1) return "5' UTR";
    if (c.indexOf("3'utr") > -1) return "3' UTR";
    if (c.indexOf("intronic") > -1) return "Intronic";
    if (c.indexOf("structural") > -1 || c.indexOf("inversion") > -1 || c.indexOf("hybrid") > -1) return "Structural";
    if (c.indexOf("gwas") > -1) return "GWAS Tag SNP";
    return "Other / Unclassified";
  }

  function validationTier(v) {
    var c = (v || "").toLowerCase();
    if (!c) return { label: "Not characterized", cls: "badge-low" };
    if (c.indexOf("clinical") > -1 || c.indexOf("serological") > -1 || c.indexOf("in vivo") > -1)
      return { label: "Clinical / Serological", cls: "badge-good" };
    if (c.indexOf("functional") > -1 || c.indexOf("cell culture") > -1 || c.indexOf("strong") > -1 || c.indexOf("moderate") > -1)
      return { label: "Functional / Cell culture", cls: "badge-mid" };
    if (c.indexOf("database") > -1) return { label: "Database only", cls: "badge-low" };
    if (c.indexOf("in silico") > -1 || c.indexOf("not characterized") > -1 || c.indexOf("inferred") > -1 || c.indexOf("provisional") > -1)
      return { label: "In silico / unvalidated", cls: "badge-low" };
    return { label: "Not characterized", cls: "badge-low" };
  }

  function auditTier(v) {
    var c = (v || "").toUpperCase();
    if (!c) return { label: "Unaudited", cls: "badge-low" };
    if (c.indexOf("FLAGGED") === 0) return { label: "Flagged", cls: "badge-flag" };
    if (c.indexOf("CORRECTED") === 0) return { label: "Corrected", cls: "badge-mid" };
    if (c.indexOf("VERIFIED") === 0) return { label: "Verified", cls: "badge-good" };
    if (c.indexOf("LIKELY VALID") === 0) return { label: "Likely valid", cls: "badge-good" };
    return { label: "Unaudited", cls: "badge-low" };
  }

  function beTier(be4, abe8) {
    var c = ((be4 || "") + " " + (abe8 || "")).toUpperCase();
    if (c.indexOf("FEASIBLE") > -1 && c.indexOf("NOT FEASIBLE") === -1 && c.indexOf("MEDIUM") === -1) return { label: "Feasible", cls: "badge-good" };
    if (c.indexOf("MEDIUM") > -1) return { label: "Medium", cls: "badge-mid" };
    if (c.indexOf("NOT FEASIBLE") > -1) return { label: "Not feasible", cls: "badge-low" };
    return { label: "Not assessed", cls: "badge-low" };
  }

  function fmtAF(x) {
    if (!x || x === "N/A") return "N/A";
    var n = parseFloat(x);
    if (isNaN(n)) return x;
    if (n === 0) return "0";
    return n.toExponential(2).replace("e-", "×10⁻").replace("+", "");
  }

  /* ---------------- multi-select dropdown ---------------- */
  // Replaces a <select> with a checkbox dropdown. The select's first option
  // ("All systems", etc.) is the empty-selection label; the rest become
  // checkboxes. An empty selection means "no filter".
  var openMultiSelects = [];

  function multiSelect(selectEl, onChange) {
    var opts = Array.from(selectEl.options);
    var allLabel = opts[0].textContent;
    var noun = allLabel.replace(/^All\s+/i, "");
    var choices = opts.slice(1).map(function (o) { return { value: o.value, label: o.textContent }; });
    var ariaLabel = selectEl.getAttribute("aria-label") || allLabel;

    var root = document.createElement("div");
    root.className = "ms";
    root.id = selectEl.id;
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "ms-btn";
    btn.setAttribute("aria-haspopup", "true");
    btn.setAttribute("aria-expanded", "false");
    btn.setAttribute("aria-label", ariaLabel);
    var btnText = document.createElement("span");
    btn.appendChild(btnText);
    btn.insertAdjacentHTML("beforeend", '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><path d="M6 9l6 6 6-6"/></svg>');

    var panel = document.createElement("div");
    panel.className = "ms-panel";
    panel.setAttribute("role", "group");
    panel.setAttribute("aria-label", ariaLabel);
    panel.hidden = true;
    var boxes = choices.map(function (c) {
      var lab = document.createElement("label");
      lab.className = "ms-opt";
      var cb = document.createElement("input");
      cb.type = "checkbox";
      cb.value = c.value;
      cb.addEventListener("change", function () { update(); onChange(); });
      lab.appendChild(cb);
      lab.appendChild(document.createTextNode(c.label));
      panel.appendChild(lab);
      return cb;
    });
    var clearBtn = document.createElement("button");
    clearBtn.type = "button";
    clearBtn.className = "ms-panel-clear";
    clearBtn.textContent = "Clear selection";
    clearBtn.addEventListener("click", function () { api.set([]); onChange(); });
    panel.appendChild(clearBtn);

    root.appendChild(btn);
    root.appendChild(panel);
    selectEl.parentNode.replaceChild(root, selectEl);

    function update() {
      var picked = choices.filter(function (c, i) { return boxes[i].checked; });
      btnText.textContent = picked.length === 0 ? allLabel
        : picked.length === 1 ? picked[0].label
        : picked.length + " " + noun;
      root.classList.toggle("is-filtered", picked.length > 0);
      clearBtn.hidden = picked.length === 0;
    }

    function setOpen(open) {
      panel.hidden = !open;
      btn.setAttribute("aria-expanded", open ? "true" : "false");
      if (!open) return;
      // On narrow screens, shift the panel left so it doesn't run off the viewport.
      panel.style.left = "";
      var overflow = panel.getBoundingClientRect().right - (document.documentElement.clientWidth - 16);
      if (overflow > 0) panel.style.left = -overflow + "px";
    }

    btn.addEventListener("click", function () {
      var open = panel.hidden;
      openMultiSelects.forEach(function (m) { m.close(); });
      setOpen(open);
    });
    document.addEventListener("click", function (e) { if (!root.contains(e.target)) setOpen(false); });
    root.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && !panel.hidden) { e.stopPropagation(); setOpen(false); btn.focus(); }
    });

    var api = {
      get: function () { return boxes.filter(function (b) { return b.checked; }).map(function (b) { return b.value; }); },
      set: function (values) { boxes.forEach(function (b) { b.checked = values.indexOf(b.value) > -1; }); update(); },
      close: function () { setOpen(false); },
    };
    openMultiSelects.push(api);
    update();
    return api;
  }

  /* ---------------- browser state / render ---------------- */
  function initBrowser() {
    var table = document.getElementById("variant-tbody");
    if (!table) return; // not on a page with the browser

    var DATA = window.VARIANT_DATA || [];
    var state = {
      q: "",
      // multi-select filters: an empty array means "all"
      system: [],
      category: [],
      validation: [],
      audit: [],
      sortKey: "variant_id",
      sortDir: 1,
    };

    var systems = [];
    DATA.forEach(function (r) {
      if (systems.indexOf(r.system) === -1) systems.push(r.system);
    });

    var els = {
      search: document.getElementById("q"),
      systemSel: document.getElementById("f-system"),
      categorySel: document.getElementById("f-category"),
      validationSel: document.getElementById("f-validation"),
      auditSel: document.getElementById("f-audit"),
      clear: document.getElementById("f-clear"),
      count: document.getElementById("result-count"),
      tbody: table,
      empty: document.getElementById("empty-state"),
      tableScroll: document.querySelector(".table-scroll"),
      systemCards: document.querySelectorAll("[data-system-card]"),
      sortButtons: document.querySelectorAll("[data-sort]"),
    };

    // Populate category/validation-tier filter options from the actual data.
    var categories = Array.from(new Set(DATA.map(function (r) { return categoryBucket(r.variant_category); } ))).sort();
    // List 5' UTR ahead of 3' UTR (gene order), not in plain alphabetical order.
    var i5 = categories.indexOf("5' UTR"), i3 = categories.indexOf("3' UTR");
    if (i5 > -1 && i3 > -1) { categories.splice(i5, 1); categories.splice(i3, 0, "5' UTR"); }
    // Catch-all bucket goes last.
    var iOther = categories.indexOf("Other / Unclassified");
    if (iOther > -1) { categories.splice(iOther, 1); categories.push("Other / Unclassified"); }
    categories.forEach(function (c) {
      var opt = document.createElement("option");
      opt.value = c; opt.textContent = c;
      els.categorySel.appendChild(opt);
    });

    function onFilterChange() {
      state.system = els.systemSel.get();
      state.category = els.categorySel.get();
      state.validation = els.validationSel.get();
      state.audit = els.auditSel.get();
      render();
    }
    els.systemSel = multiSelect(els.systemSel, onFilterChange);
    els.categorySel = multiSelect(els.categorySel, onFilterChange);
    els.validationSel = multiSelect(els.validationSel, onFilterChange);
    els.auditSel = multiSelect(els.auditSel, onFilterChange);

    function inSet(selected, value) {
      return selected.length === 0 || selected.indexOf(value) > -1;
    }

    function matches(r) {
      if (!inSet(state.system, r.system)) return false;
      if (!inSet(state.category, categoryBucket(r.variant_category))) return false;
      if (!inSet(state.validation, validationTier(r.validation_level).label)) return false;
      if (!inSet(state.audit, auditTier(r.audit_status).label)) return false;
      if (state.q) {
        var hay = [r.variant_id, r.gene, r.hgvs, r.alternative_notation, r.phenotype, r.dbsnp_rs, r.allele_background, r.key_reference]
          .join(" ").toLowerCase();
        if (hay.indexOf(state.q.toLowerCase()) === -1) return false;
      }
      return true;
    }

    function sortVal(r, key) {
      if (key === "af") return parseFloat(r.gnomad_v4_af_global) || -1;
      return (r[key] || "").toString().toLowerCase();
    }

    function render() {
      var filtered = DATA.filter(matches);
      filtered.sort(function (a, b) {
        var av = sortVal(a, state.sortKey), bv = sortVal(b, state.sortKey);
        if (av < bv) return -1 * state.sortDir;
        if (av > bv) return 1 * state.sortDir;
        return 0;
      });

      var total = filtered.length;

      els.count.textContent = total.toLocaleString() + (total === 1 ? " variant" : " variants");

      els.tbody.innerHTML = "";
      if (total === 0) {
        els.empty.style.display = "block";
        els.tbody.parentElement.parentElement.style.display = "none";
      } else {
        els.empty.style.display = "none";
        els.tbody.parentElement.parentElement.style.display = "";
        filtered.forEach(function (r) {
          var val = validationTier(r.validation_level);
          var aud = auditTier(r.audit_status);
          var tr = document.createElement("tr");
          tr.setAttribute("tabindex", "0");
          tr.setAttribute("role", "button");
          tr.setAttribute("aria-label", "View details for " + r.variant_id);
          tr.innerHTML =
            '<td><div class="cell-primary mono">' + esc(r.variant_id) + '</div>' +
              '<div class="cell-sub">' + esc(r.system_label) + '</div></td>' +
            '<td class="mono">' + esc(r.hgvs || "N/A") + '</td>' +
            '<td class="cell-trunc" title="' + esc(r.phenotype || "") + '">' + esc(r.phenotype || "N/A") + '</td>' +
            '<td>' + esc(categoryBucket(r.variant_category)) + '</td>' +
            '<td class="mono">' + esc(fmtAF(r.gnomad_v4_af_global)) + '</td>' +
            '<td><span class="badge ' + val.cls + '">' + val.label + '</span></td>' +
            '<td><span class="badge ' + aud.cls + '">' + aud.label + '</span></td>';
          tr.addEventListener("click", function () { openDrawer(r); });
          tr.addEventListener("keydown", function (e) { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); openDrawer(r); } });
          els.tbody.appendChild(tr);
        });
      }

      // new filter/sort results start from the top of the scrollable table
      els.tableScroll.scrollTop = 0;

      els.sortButtons.forEach(function (b) {
        var arrow = b.querySelector(".sort-arrow");
        if (!arrow) return;
        arrow.textContent = b.dataset.sort === state.sortKey ? (state.sortDir === 1 ? "↑" : "↓") : "";
      });

      els.systemCards.forEach(function (card) {
        card.classList.toggle("is-active", state.system.indexOf(card.dataset.systemCard) > -1);
      });
    }

    els.search.addEventListener("input", function () { state.q = this.value; render(); });
    els.clear.addEventListener("click", function () {
      state.q = ""; els.search.value = "";
      [els.systemSel, els.categorySel, els.validationSel, els.auditSel].forEach(function (m) { m.set([]); });
      onFilterChange();
    });

    els.sortButtons.forEach(function (btn) {
      btn.addEventListener("click", function () {
        var key = btn.dataset.sort;
        if (state.sortKey === key) { state.sortDir *= -1; } else { state.sortKey = key; state.sortDir = 1; }
        render();
      });
    });

    els.systemCards.forEach(function (card) {
      card.addEventListener("click", function () {
        // Card click shows just that system; clicking it again when it's the
        // only one selected clears the system filter.
        var sys = card.dataset.systemCard;
        var only = state.system.length === 1 && state.system[0] === sys;
        els.systemSel.set(only ? [] : [sys]);
        onFilterChange();
        document.getElementById("browse").scrollIntoView({ behavior: "smooth", block: "start" });
      });
    });

    /* ---------------- detail drawer ---------------- */
    var overlay = document.getElementById("drawer-overlay");
    var drawer = document.getElementById("drawer");
    var drawerBody = document.getElementById("drawer-body");
    var drawerTitle = document.getElementById("drawer-title");
    var drawerSub = document.getElementById("drawer-sub");

    function row(label, value, mono) {
      if (!value) value = "N/A";
      return '<div class="field-row"><dt>' + label + '</dt><dd' + (mono ? ' class="mono"' : '') + '>' + esc(value) + '</dd></div>';
    }

    function openDrawer(r) {
      drawerTitle.textContent = r.variant_id;
      drawerSub.textContent = r.gene + " · " + r.system_label;

      var val = validationTier(r.validation_level);
      var aud = auditTier(r.audit_status);
      var be = beTier(r.be4max_feasibility, r.abe8e_feasibility);

      var citeText = (r.key_reference || "Reference not specified") +
        ". Cited in: Blood Group Non-Coding Variant Database, variant " + r.variant_id +
        " (" + r.gene + "). Compiled by Jun Liu, MD, PhD (Chai Lab, Brigham and Women's Hospital / Harvard Medical School).";

      drawerBody.innerHTML =
        '<div class="field-group"><h4>Identity</h4><div class="field-list">' +
          row("HGVS", r.hgvs, true) +
          row("Alt. notation", r.alternative_notation) +
          row("Allele bkgd.", r.allele_background) +
          row("ISBT allele", r.isbt_allele_designation) +
          row("Phenotype", r.phenotype) +
        '</div></div>' +

        '<div class="field-group"><h4>Genomic location</h4><div class="field-list">' +
          row("Gene", r.gene, true) +
          row("Chromosome", r.chromosome + (r.strand ? " (" + r.strand + " strand)" : "")) +
          row("GRCh38", r.grch38_coordinate, true) +
          row("Region", r.region) +
          row("dbSNP", r.dbsnp_rs, true) +
        '</div></div>' +

        '<div class="field-group"><h4>Classification</h4><div class="field-list">' +
          row("Category", r.variant_category) +
          row("Mutation type", r.mutation_type) +
          '<div class="field-row"><dt>Validation</dt><dd><span class="badge ' + val.cls + '">' + val.label + '</span> <span style="color:var(--muted);font-size:12.5px">' + esc(r.validation_level || "") + '</span></dd></div>' +
          '<div class="field-row"><dt>Audit status</dt><dd><span class="badge ' + aud.cls + '">' + aud.label + '</span> <span style="color:var(--muted);font-size:12.5px">' + esc((r.audit_status || "").replace(/^(FLAGGED|CORRECTED|VERIFIED|LIKELY VALID):?\s*/, "")) + '</span></dd></div>' +
        '</div></div>' +

        '<div class="field-group"><h4>Molecular mechanism</h4><div class="mech-box">' + esc(r.molecular_mechanism || "Not described.") + '</div></div>' +

        '<div class="field-group"><h4>Population frequency</h4><div class="field-list">' +
          row("gnomAD v4 (global)", fmtAF(r.gnomad_v4_af_global), true) +
          row("gnomAD v4 (AFR)", fmtAF(r.gnomad_v4_af_afr), true) +
          row("gnomAD v4 (EUR)", fmtAF(r.gnomad_v4_af_eur), true) +
          row("TOPMed", fmtAF(r.topmed_af), true) +
          row("Reported population", r.population) +
        '</div></div>' +

        '<div class="field-group"><h4>Base editing feasibility</h4><div class="field-list">' +
          '<div class="field-row"><dt>Overall</dt><dd><span class="badge ' + be.cls + '">' + be.label + '</span></dd></div>' +
          row("BE4max (C→T)", r.be4max_feasibility) +
          row("ABE8e (A→G)", r.abe8e_feasibility) +
          row("Guide notes", r.be_guide_sequence_notes) +
          row("Bystander edits", r.bystander_edits) +
        '</div></div>' +

        '<div class="field-group"><h4>Reference & links</h4>' +
          '<p style="margin-bottom:10px">' + esc(r.key_reference || "Not specified") + (r.first_report_year ? " (first reported " + esc(r.first_report_year) + ")" : "") + '</p>' +
          '<div class="link-row">' +
            (r.pubmed_source_url ? '<a href="' + esc(r.pubmed_source_url) + '" target="_blank" rel="noopener">PubMed ↗</a>' : '') +
            (r.gnomad_url ? '<a href="' + esc(r.gnomad_url) + '" target="_blank" rel="noopener">gnomAD ↗</a>' : '') +
          '</div>' +
        '</div>' +

        '<div class="field-group"><h4>Cite this entry</h4><div class="cite-box">' + esc(citeText) + '</div></div>';

      overlay.classList.add("is-open");
      drawer.classList.add("is-open");
      drawer.focus();
    }

    function closeDrawer() {
      overlay.classList.remove("is-open");
      drawer.classList.remove("is-open");
    }

    overlay.addEventListener("click", closeDrawer);
    document.getElementById("drawer-close").addEventListener("click", closeDrawer);
    document.addEventListener("keydown", function (e) { if (e.key === "Escape") closeDrawer(); });

    render();

    // Deep-link support: ?system=RHD or #RHD-NC-004
    var params = new URLSearchParams(window.location.search);
    if (params.get("system")) {
      els.systemSel.set(params.get("system").split(","));
      onFilterChange();
    }
    if (window.location.hash) {
      var wanted = window.location.hash.replace("#", "");
      var match = DATA.find(function (r) { return r.variant_id === wanted; });
      if (match) openDrawer(match);
    }
  }

  /* ---------------- stats page ---------------- */
  function initStats() {
    var root = document.getElementById("stats-root");
    if (!root) return;
    var DATA = window.VARIANT_DATA || [];

    function count(getKey) {
      var c = {};
      DATA.forEach(function (r) {
        var k = getKey(r);
        c[k] = (c[k] || 0) + 1;
      });
      return c;
    }

    function renderBars(elId, counts, order, tierClassFn) {
      var el = document.getElementById(elId);
      if (!el) return;
      var entries = order ? order.map(function (k) { return [k, counts[k] || 0]; }) : Object.entries(counts).sort(function (a, b) { return b[1] - a[1]; });
      var max = Math.max.apply(null, entries.map(function (e) { return e[1]; }).concat([1]));
      el.innerHTML = entries.map(function (e) {
        var pct = Math.max((e[1] / max) * 100, e[1] > 0 ? 2 : 0);
        var cls = tierClassFn ? tierClassFn(e[0]) : "";
        return '<div class="bar-row"><div class="bar-label" title="' + esc(e[0]) + '">' + esc(e[0]) + '</div>' +
          '<div class="bar-track"><div class="bar-fill ' + cls + '" style="width:' + pct + '%"></div></div>' +
          '<div class="bar-val">' + e[1] + '</div></div>';
      }).join("");
    }

    var SYSTEM_ORDER = ["ABO", "RHD", "RHCE", "Duffy", "Kell", "Kidd", "MNS", "KellOther"];
    var SYSTEM_LABELS = { ABO: "ABO", RHD: "RHD", RHCE: "RHCE", Duffy: "Duffy (ACKR1)", Kell: "Kell (KEL)", Kidd: "Kidd (SLC14A1)", MNS: "MNS (GYPA/GYPB)", KellOther: "Kell Other" };
    var bySystem = count(function (r) { return r.system; });
    var bySystemLabeled = {};
    SYSTEM_ORDER.forEach(function (s) { bySystemLabeled[SYSTEM_LABELS[s]] = bySystem[s] || 0; });
    renderBars("chart-system", bySystemLabeled, SYSTEM_ORDER.map(function (s) { return SYSTEM_LABELS[s]; }));

    renderBars("chart-category", count(function (r) { return categoryBucket(r.variant_category); }));

    var VAL_ORDER = ["Clinical / Serological", "Functional / Cell culture", "Database only", "In silico / unvalidated", "Not characterized"];
    function valCls(label) {
      var map = { "Clinical / Serological": "tier-good", "Functional / Cell culture": "tier-mid" };
      return map[label] || "tier-low";
    }
    renderBars("chart-validation", count(function (r) { return validationTier(r.validation_level).label; }), VAL_ORDER, valCls);

    var AUDIT_ORDER = ["Verified", "Likely valid", "Corrected", "Flagged", "Unaudited"];
    function auditCls(label) {
      var map = { "Verified": "tier-good", "Likely valid": "tier-good", "Corrected": "tier-mid", "Flagged": "tier-flag" };
      return map[label] || "tier-low";
    }
    renderBars("chart-audit", count(function (r) { return auditTier(r.audit_status).label; }), AUDIT_ORDER, auditCls);

    var BE_ORDER = ["Feasible", "Medium", "Not feasible", "Not assessed"];
    function beCls(label) {
      var map = { "Feasible": "tier-good", "Medium": "tier-mid" };
      return map[label] || "tier-low";
    }
    renderBars("chart-be", count(function (r) { return beTier(r.be4max_feasibility, r.abe8e_feasibility).label; }), BE_ORDER, beCls);

    // headline stat tiles
    // Some records store two genes in one field (e.g. "GYPA/GYPB" for MNS);
    // split on "/" so the gene count reflects distinct gene loci, not strings.
    var geneSet = new Set();
    DATA.forEach(function (r) {
      (r.gene || "").split("/").forEach(function (g) { if (g) geneSet.add(g.trim()); });
    });
    var genes = Array.from(geneSet);
    var refs = new Set();
    DATA.forEach(function (r) {
      (r.key_reference || "").split(";").forEach(function (seg) {
        var m = seg.match(/PMID[:\s]*\d{6,9}/);
        if (m) refs.add(m[0]);
      });
    });
    var withAF = DATA.filter(function (r) { return r.gnomad_v4_af_global && r.gnomad_v4_af_global !== "N/A"; }).length;
    var setText = function (id, v) { var e = document.getElementById(id); if (e) e.textContent = v; };
    setText("stat-total", DATA.length);
    setText("stat-genes", genes.length);
    setText("stat-refs", refs.size + "+");
    setText("stat-af", withAF);
  }

  function initCopyButtons() {
    document.querySelectorAll("[data-copy-target]").forEach(function (btn) {
      var label = btn.textContent;
      btn.addEventListener("click", function () {
        var target = document.getElementById(btn.dataset.copyTarget);
        if (!target) return;
        var text = target.innerText || target.textContent;
        navigator.clipboard.writeText(text).then(function () {
          btn.textContent = "Copied";
          setTimeout(function () { btn.textContent = label; }, 1600);
        });
      });
    });
  }

  document.addEventListener("DOMContentLoaded", function () {
    initTheme();
    initNavToggle();
    initBrowser();
    initStats();
    initCopyButtons();
    var yearEl = document.getElementById("site-year");
    if (yearEl) yearEl.textContent = new Date().getFullYear();
  });
})();
